async function main() {
  for (const [chapterId, qs] of Object.entries(questions)) {
    console.log('Seeding', qs.length, 'questions for chapter', chapterId);
    for (const q of qs) {
      await prisma.question.create({ data: { chapterId, ...q } });
    }
    console.log('Done for chapter', chapterId);
  }
  console.log('\nBatch 1 complete.');
}

main().catch(console.error).finally(() => prisma.$disconnect());
